# ---------------------------------------------------------------- checks
_code = s.split('"""', 2)[2]
assert "@PKG@.RbCfg.MAX)" not in _code and "@PKG@.RbCfg.MAX;" not in _code.replace("int max = @PKG@.RbCfg.MAX;", "").replace("int mx3 = @PKG@.RbCfg.MAX;", ""), \
    "0.3.6: every reader of the max goes through lim / maxTxt / ofMax (or handles 0 itself)"
assert _code.count("@PKG@.RbCfg.MAX") == 2, _code.count("@PKG@.RbCfg.MAX")
assert (s.count("registerCommand("), s.count("registerSystem(")) == (CMD0, SYS0), "0.3.6: no command / system change"
_a, _b = S0.split(LF), s.split(LF)
_hunks = [op for op in difflib.SequenceMatcher(None, _a, _b, autojunk=False).get_opcodes() if op[0] != "equal"]
_gone = [(i, _a[i]) for op in _hunks for i in range(op[1], op[2])]
_allowed = set()
for _o in OLDS:
    _allowed.update(_o.split(LF))
_bad = [(i, ln) for i, ln in _gone if ln not in _allowed and not any(_o in ln for _o in OLDS if LF not in _o)]
assert not _bad, "0.3.5 lines changed outside the planned places: %r" % _bad[:5]
if os.path.exists(dst):
    os.remove(dst)
compile(s, dst, "exec")
open(dst, "wb").write(s.replace(LF, NL).encode("utf8"))
print("wrote", dst, len(s), "chars;", len(_hunks), "diff hunks vs 0.3.5,", len(_gone), "0.3.5 lines replaced;", len(OLDS), "anchors")
